  public ODRAttestationT ATTESTATION { get; set; }

  public ODRT() {
    this.RUN_ID = null;
    this.STARTED_AT = null;
    this.COMPLETED_AT = null;
    this.CONFIGURATION = null;
    this.CONVERGENCE_REASON = odrConvergenceReason.UNSPECIFIED;
    this.ITERATIONS = null;
    this.EDITED_OBSERVATIONS = null;
    this.ESTIMATED_PARAMETERS = null;
    this.ESTIMATED_EPOCH_STATE = null;
    this.COVARIANCE_DIMENSION = 0;
    this.STATE_COVARIANCE = null;
    this.OCM_CONTENT_ID = null;
    this.FILTER_HISTORY = null;
    this.RESIDUAL_RMS = 0.0;
    this.TRACE_ID = null;
    this.ATTESTATION = null;
  }
  public static ODRT DeserializeFromBinary(byte[] fbBuffer) {
    return ODR.GetRootAsODR(new ByteBuffer(fbBuffer)).UnPack();
  }
  public byte[] SerializeToBinary() {
    var fbb = new FlatBufferBuilder(0x10000);
    ODR.FinishODRBuffer(fbb, ODR.Pack(fbb, this));
    return fbb.DataBuffer.ToSizedArray();
  }
}


static public class ODRVerify
{
  static public bool Verify(Google.FlatBuffers.Verifier verifier, uint tablePos)
  {
    return verifier.VerifyTableStart(tablePos)
      && verifier.VerifyString(tablePos, 4 /*RUN_ID*/, true)
      && verifier.VerifyString(tablePos, 6 /*STARTED_AT*/, false)
      && verifier.VerifyString(tablePos, 8 /*COMPLETED_AT*/, false)
      && verifier.VerifyTable(tablePos, 10 /*CONFIGURATION*/, ODRSolverConfigurationVerify.Verify, false)
      && verifier.VerifyField(tablePos, 12 /*CONVERGENCE_REASON*/, 1 /*odrConvergenceReason*/, 1, false)
      && verifier.VerifyVectorOfTables(tablePos, 14 /*ITERATIONS*/, ODRIterationStatisticsVerify.Verify, false)
      && verifier.VerifyVectorOfTables(tablePos, 16 /*EDITED_OBSERVATIONS*/, ODREditedObservationVerify.Verify, false)
      && verifier.VerifyVectorOfTables(tablePos, 18 /*ESTIMATED_PARAMETERS*/, ODREstimatedParameterVerify.Verify, false)
      && verifier.VerifyTable(tablePos, 20 /*ESTIMATED_EPOCH_STATE*/, FRMStateVectorVerify.Verify, false)
      && verifier.VerifyField(tablePos, 22 /*COVARIANCE_DIMENSION*/, 4 /*uint*/, 4, false)
      && verifier.VerifyVectorOfData(tablePos, 24 /*STATE_COVARIANCE*/, 8 /*double*/, false)
      && verifier.VerifyString(tablePos, 26 /*OCM_CONTENT_ID*/, true)
      && verifier.VerifyVectorOfTables(tablePos, 28 /*FILTER_HISTORY*/, ODRFilterEpochVerify.Verify, false)
      && verifier.VerifyField(tablePos, 30 /*RESIDUAL_RMS*/, 8 /*double*/, 8, false)
      && verifier.VerifyString(tablePos, 32 /*TRACE_ID*/, false)
      && verifier.VerifyTable(tablePos, 34 /*ATTESTATION*/, ODRAttestationVerify.Verify, false)
      && verifier.VerifyTableEnd(tablePos);
  }
}
